"""Trailing blocks of the ribbon tabs (hst-ribbon-trailing-blocks.patch, generated by
scripts/patches/generate-ribbon-trailing-blocks.py; hst-ribbon-addons-block.patch). Reads the patches and runs the
generator on a small fixture."""
import importlib.util
import os
import tempfile
import unittest

from _paths import ROOT
from test_ribbon_group_button import added, sections

PATCHES = os.path.join(ROOT, "patches", "libreoffice")
BLOCKS = os.path.join(PATCHES, "hst-ribbon-trailing-blocks.patch")
ADDONS = os.path.join(PATCHES, "hst-ribbon-addons-block.patch")
spec = importlib.util.spec_from_file_location("generate_ribbon_trailing_blocks",
                                              os.path.join(ROOT, "scripts/patches/generate-ribbon-trailing-blocks.py"))
gen = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gen)


def page(tab, body, context=""):
    style = f'<style><class name="context-{context}"/></style>' if context else ""
    return f"""            <child>
              <object class="GtkBox" id="{tab}Page">
{body}                {style}
              </object>
            </child>
            <child type="tab">
              <object class="GtkLabel" id="{tab}Label">
                <property name="label">{tab}</property>
              </object>
            </child>
"""


def block(ident, menu, icons):
    items = "".join(f"""                        <child>
                          <object class="GtkToolButton" id="{ident}-{c}">
                            <property name="action-name">.uno:{c}</property>
                          </object>
                        </child>
""" for c in icons)
    return f"""                <child>
                  <object class="sfxlo-DropdownBox" id="{ident}">
                    <child>
                      <object class="svtlo-ManagedMenuButton" id="{ident}-Button:{menu}">
                      </object>
                    </child>
                    <child>
                      <object class="sfxlo-NotebookbarToolBox" id="{ident}-Icons">
{items}                      </object>
                    </child>
                  </object>
                </child>
"""


def button(command):
    return f"""                <child>
                  <object class="GtkToolButton" id="btn{command}">
                    <property name="action-name">.uno:{command}</property>
                  </object>
                </child>
"""


FIXTURE = f"""<?xml version="1.0" encoding="UTF-8"?>
<interface>
  <object class="GtkMenu" id="Menu A"><child><object class="GtkMenuItem" id="a1"><property name="action-name">.uno:Zoom</property></object></child></object>
  <object class="GtkMenu" id="Menu B"><child><object class="GtkMenuItem" id="b1"><property name="action-name">.uno:Only</property></object></child></object>
  <object class="sfxlo-NotebookbarTabControl" id="tabs">
{page("Home", button("Zoom") + button("Paste"))}{page("View", button("Bold") + block("View-Menu", "Menu B", ["Zoom", "Paste"]))}{page("Pic", block("Pic-Menu", "Menu A", ["Bold"]), "Graphic")}{page("Help", button("About"))}{page("Extension", button("Macro"))}  </object>
</interface>
"""


class TrailingBlocks(unittest.TestCase):
    def transform(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "notebookbar.ui")
            with open(path, "w", encoding="utf-8") as handle:
                handle.write(FIXTURE)
            return gen.transform(path)[1]

    def test_block_without_only_here_commands_goes(self):
        out = self.transform()
        self.assertNotIn('id="Pic-Menu"', out)  # Zoom and Bold are on the ribbon
        self.assertIn('id="View-Menu"', out)  # its menu holds Only
        # the kept block loses the icons that repeat ribbon commands; its emptied toolbox goes too
        self.assertNotIn('id="View-Menu-Zoom"', out)
        self.assertNotIn('id="View-Menu-Paste"', out)
        self.assertNotIn('id="View-Menu-Icons"', out)

    def test_help_and_extension_before_contextual_tabs(self):
        out = self.transform()
        order = [out.index(f'id="{t}Label"') for t in ("View", "Help", "Extension", "Pic")]
        self.assertEqual(order, sorted(order))

    def test_patch_scope(self):
        self.assertEqual(sorted(sections(BLOCKS)), sorted(gen.UI.values()))  # Writer, Sheets, Slides; not Draw
        removed = "".join("".join(v[1]) for v in sections(BLOCKS).values())
        for ident in ("Print-Menu", "Form-Menu", "3dObject-Menu", "MasterPage-Menu"):
            self.assertIn(f'id="{ident}"', removed)
        for ident in ("File-Menu", "Home-Menu", "Insert-Menu"):
            self.assertNotIn(f'<object class="sfxlo-DropdownBox" id="{ident}">', removed)

    def test_extension_block_hidden_without_addons(self):
        code = added(ADDONS, "vcl/source/control/PriorityHBox.cxx")
        self.assertIn("bool lcl_HstEmptyAddonBox(const vcl::Window& rBox)", code)
        self.assertIn("bEmpty = pItem->GetType() == WindowType::PUSHBUTTON;", code)
        self.assertIn("dynamic_cast<DropdownBox*>(pChild) || pChild->GetType() == WindowType::FIXEDLINE", code)

    def test_in_series_after_caption_style(self):
        with open(os.path.join(PATCHES, "series"), encoding="utf-8") as handle:
            names = [line.strip() for line in handle if line.strip() and not line.startswith("#")]
        self.assertLess(names.index("hst-ribbon-caption-style.patch"), names.index("hst-ribbon-trailing-blocks.patch"))
        self.assertLess(names.index("hst-ribbon-trailing-blocks.patch"), names.index("hst-ribbon-addons-block.patch"))


if __name__ == "__main__":
    unittest.main()
